package com.emerald.society.controller;

import com.emerald.society.audit.AuditTrail;
import com.emerald.society.security.SocietyAccess;
import tools.jackson.databind.json.JsonMapper;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.scheduling.annotation.Scheduled;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.YearMonth;
import java.time.LocalDate;

/** Rental workflows share flat-scoped records while retaining independent permission checks. */
@RestController
@RequestMapping("/api/v1/rental")
public class RentalOperationsController {
    private static final Map<String,String> VIEW = Map.of("payments","RENT_VIEW", "maintenance","MAINTENANCE_VIEW", "leases","LEASE_VIEW", "viewings","VIEWING_VIEW");
    private static final Map<String,String> CREATE = Map.of("payments","RENT_MANAGE", "maintenance","MAINTENANCE_CREATE", "leases","LEASE_MANAGE", "viewings","VIEWING_MANAGE");
    private static final Map<String,String> MANAGE = Map.of("payments","RENT_MANAGE", "maintenance","MAINTENANCE_MANAGE", "leases","LEASE_MANAGE", "viewings","VIEWING_MANAGE");
    private static final Map<String,String> TYPES = Map.of("payments","PAYMENT", "maintenance","MAINTENANCE", "leases","LEASE", "viewings","VIEWING");
    private final JdbcTemplate db;
    private final SocietyAccess access;
    private final JsonMapper json;
    private final AuditTrail audit;
    public RentalOperationsController(JdbcTemplate db, SocietyAccess access, JsonMapper json, AuditTrail audit) { this.db=db; this.access=access; this.json=json; this.audit=audit; }

    @GetMapping("/{resource}")
    public List<Map<String,Object>> list(@PathVariable String resource, @RequestParam(required=false) UUID flatId) {
        requireResource(resource); var actor=access.identity();
        boolean society=access.has(VIEW.get(resource),"SOCIETY");
        if(!society&&(!access.has(VIEW.get(resource),"OWN_FLATS")||actor==null||actor.flatIds().isEmpty()||(flatId!=null&&!actor.flatIds().contains(flatId))))throw new AccessDeniedException("Permission denied for this flat");
        String sql="SELECT r.id,r.flat_id,r.member_id,CASE WHEN r.operation_type='PAYMENT' THEN CASE WHEN COALESCE(x.amount_paid,0)>=COALESCE((r.details->>'amount')::numeric,0) OR (r.status='PAID' AND COALESCE(x.receipt_count,0)=0) THEN 'PAID' WHEN COALESCE(x.amount_paid,0)>0 THEN 'PARTIALLY_PAID' WHEN (r.details->>'dueDate')::date<CURRENT_DATE THEN 'OVERDUE' ELSE 'DUE' END ELSE r.status END AS status,r.details,r.created_by,r.created_at,r.updated_at,r.version,COALESCE(x.amount_paid,0) amount_paid,COALESCE(x.receipt_count,0) receipt_count,COALESCE(x.pending_count,0) pending_count FROM rental_operations r LEFT JOIN LATERAL (SELECT SUM(amount) amount_paid,COUNT(*) receipt_count,COUNT(*) FILTER(WHERE NOT reconciled) pending_count FROM rent_payment_receipts WHERE payment_id=r.id) x ON TRUE WHERE r.operation_type=?";
        List<Object> args=new ArrayList<>(List.of(TYPES.get(resource)));
        if (access.has(VIEW.get(resource),"SOCIETY")) { if(flatId!=null){sql+=" AND r.flat_id=?";args.add(flatId);} }
        else { var flats=access.ownFlats(); if(flats.isEmpty()) return List.of(); sql+=" AND r.flat_id IN ("+String.join(",",Collections.nCopies(flats.size(),"?"))+ ")";args.addAll(flats);if(flatId!=null){sql+=" AND r.flat_id=?";args.add(flatId);} }
        sql+=" ORDER BY r.created_at DESC LIMIT 200";
        boolean maySeeMembers=society;
        return db.query(sql,(rs,n)->{Map<String,Object> result=row(rs.getObject("id",UUID.class),rs.getObject("flat_id",UUID.class),maySeeMembers?rs.getObject("member_id",UUID.class):null,rs.getString("status"),rs.getString("details"),rs.getObject("created_by",UUID.class),rs.getTimestamp("created_at").toInstant(),rs.getTimestamp("updated_at").toInstant(),rs.getLong("version"));if("payments".equals(resource)){Map<?,?> details=(Map<?,?>)result.get("details");BigDecimal amount=new BigDecimal(details.get("amount").toString());BigDecimal paid=rs.getBigDecimal("amount_paid");boolean legacyPaid="PAID".equals(rs.getString("status"))&&rs.getInt("receipt_count")==0;if(legacyPaid)paid=amount;result.put("amountPaid",paid);result.put("balance",amount.subtract(paid).max(BigDecimal.ZERO));result.put("receiptCount",rs.getInt("receipt_count"));result.put("reconciliationStatus",legacyPaid?"LEGACY":rs.getInt("receipt_count")==0?"NONE":rs.getInt("pending_count")>0?"PENDING":"RECONCILED");}return result;},args.toArray());
    }

    @GetMapping("/schedules")
    public List<Map<String,Object>> schedules(@RequestParam(required=false) UUID flatId){requireRentView(flatId);String sql="SELECT id,flat_id,amount,due_day,start_period,end_period,active,version FROM rent_schedules";List<Object> args=new ArrayList<>();if(access.has("RENT_VIEW","SOCIETY")){if(flatId!=null){sql+=" WHERE flat_id=?";args.add(flatId);}}else{var flats=access.ownFlats();if(flats.isEmpty())return List.of();sql+=" WHERE flat_id IN ("+String.join(",",Collections.nCopies(flats.size(),"?"))+")";args.addAll(flats);if(flatId!=null){sql+=" AND flat_id=?";args.add(flatId);}}sql+=" ORDER BY flat_id,active DESC,start_period";return db.query(sql,(rs,n)->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",rs.getObject("id",UUID.class));m.put("flatId",rs.getObject("flat_id",UUID.class));m.put("amount",rs.getBigDecimal("amount"));m.put("dueDay",rs.getInt("due_day"));m.put("startPeriod",rs.getString("start_period"));m.put("endPeriod",rs.getString("end_period"));m.put("active",rs.getBoolean("active"));m.put("version",rs.getLong("version"));return m;},args.toArray());}

    @PostMapping("/schedules") @ResponseStatus(HttpStatus.CREATED) @Transactional
    public Map<String,Object> createSchedule(@RequestBody Map<String,Object> body){if(body.keySet().stream().anyMatch(k->!Set.of("flatId","amount","dueDay","startPeriod","endPeriod").contains(k)))throw bad("Unsupported schedule field");UUID flat=uuid(body.get("flatId"));requirePermission("RENT_MANAGE",flat);BigDecimal amount=money(body.get("amount"));int dueDay=integer(body.get("dueDay"),1,31);String start=period(body.get("startPeriod"));String end=body.get("endPeriod")==null||body.get("endPeriod").toString().isBlank()?null:period(body.get("endPeriod"));if(end!=null&&end.compareTo(start)<0)throw bad("endPeriod must not precede startPeriod");UUID id=UUID.randomUUID();try{db.update("INSERT INTO rent_schedules(id,flat_id,amount,due_day,start_period,end_period,created_by) VALUES(?,?,?,?,?,?,?)",id,flat,amount,dueDay,start,end,access.identity().adminId());}catch(org.springframework.dao.DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"An active rent schedule already exists for this flat",e);}audit.record("CREATE_RENT_SCHEDULE","RENT_SCHEDULE",id,null,body);return schedule(id,flat,amount,dueDay,start,end,true,0);}

    @PutMapping("/schedules/{id}") @Transactional
    public Map<String,Object> updateSchedule(@PathVariable UUID id,@RequestBody Map<String,Object> body){var old=db.query("SELECT flat_id,amount,due_day,start_period,end_period,active,version FROM rent_schedules WHERE id=?",(rs,n)->new Object[]{rs.getObject(1,UUID.class),rs.getBigDecimal(2),rs.getInt(3),rs.getString(4),rs.getString(5),rs.getBoolean(6),rs.getLong(7)},id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));UUID flat=(UUID)old[0];requirePermission("RENT_MANAGE",flat);long v=((Number)old[6]).longValue();if(integer(body.get("version"),0,Integer.MAX_VALUE)!=v)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Supply the current schedule version");if(body.keySet().stream().anyMatch(k->!Set.of("amount","dueDay","startPeriod","endPeriod","active","version").contains(k)))throw bad("Unsupported schedule field");BigDecimal amount=body.containsKey("amount")?money(body.get("amount")):(BigDecimal)old[1];int day=body.containsKey("dueDay")?integer(body.get("dueDay"),1,31):(Integer)old[2];String start=body.containsKey("startPeriod")?period(body.get("startPeriod")):(String)old[3];String end=body.containsKey("endPeriod")?(body.get("endPeriod")==null||body.get("endPeriod").toString().isBlank()?null:period(body.get("endPeriod"))):(String)old[4];boolean active=body.containsKey("active")?Boolean.TRUE.equals(body.get("active")):(Boolean)old[5];if(body.containsKey("active")&&!(body.get("active") instanceof Boolean))throw bad("active must be boolean");if(end!=null&&end.compareTo(start)<0)throw bad("endPeriod must not precede startPeriod");try{int n=db.update("UPDATE rent_schedules SET amount=?,due_day=?,start_period=?,end_period=?,active=?,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=? AND version=?",amount,day,start,end,active,id,v);if(n==0)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Schedule version is stale");}catch(org.springframework.dao.DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"An active rent schedule already exists for this flat",e);}audit.record("UPDATE_RENT_SCHEDULE","RENT_SCHEDULE",id,Map.of("version",v,"active",old[5]),body);return schedule(id,flat,amount,day,start,end,active,v+1);}

    @PostMapping("/payments/generate") @Transactional
    public Map<String,Object> generate(@RequestBody Map<String,Object> body){if(body.keySet().stream().anyMatch(k->!Set.of("period").contains(k)))throw bad("Only period is accepted");String p=period(body.get("period"));if(!access.has("RENT_MANAGE","SOCIETY"))throw new AccessDeniedException("Society rent management permission required");return generatePeriod(p,access.identity().adminId());}

    @Scheduled(cron="${rental.payments.generation-cron:0 15 1 * * *}",zone="UTC") @Transactional
    public void generateCurrentPeriod(){generatePeriod(YearMonth.now(java.time.Clock.systemUTC()).toString(),UUID.nameUUIDFromBytes("emerald-rent-scheduler".getBytes(java.nio.charset.StandardCharsets.UTF_8)));}

    private Map<String,Object> generatePeriod(String p,UUID createdBy){YearMonth ym=YearMonth.parse(p);if(ym.isAfter(YearMonth.now(java.time.Clock.systemUTC())))throw bad("Rent cannot be generated for a future period");var schedules=db.query("SELECT id,flat_id,amount,due_day FROM rent_schedules WHERE active AND start_period<=? AND (end_period IS NULL OR end_period>=?) ORDER BY flat_id",(rs,n)->new Object[]{rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getBigDecimal(3),rs.getInt(4)},p,p);int generated=0;for(Object[] s:schedules){UUID flat=(UUID)s[1];UUID id=UUID.randomUUID();LocalDate due=ym.atDay(Math.min((Integer)s[3],ym.lengthOfMonth()));Map<String,Object> details=Map.of("flatId",flat,"period",p,"amount",s[2],"dueDate",due.toString());try{int n=db.update("INSERT INTO rental_operations(id,operation_type,flat_id,status,details,created_by) VALUES(?,'PAYMENT',?,'DUE',?::jsonb,?) ON CONFLICT DO NOTHING",id,flat,json.writeValueAsString(details),createdBy);if(n>0){generated++;audit.record("GENERATE_RENT_PAYMENT","RENTAL_OPERATION",id,null,details);}}catch(Exception e){if(e instanceof ResponseStatusException r)throw r;throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Rent generation failed",e);}}return Map.of("period",p,"generated",generated,"matchedSchedules",schedules.size(),"existing",schedules.size()-generated);}

    @GetMapping("/payments/{id}/receipts") public List<Map<String,Object>> receipts(@PathVariable UUID id){var p=payment(id,false);requirePermission("RENT_VIEW",(UUID)p[0]);return db.query("SELECT id,amount,reference,received_at,reconciled,reconciliation_reference,reconciled_at,created_at FROM rent_payment_receipts WHERE payment_id=? ORDER BY received_at,id",(rs,n)->{Map<String,Object> m=new LinkedHashMap<>();m.put("id",rs.getObject("id",UUID.class));m.put("amount",rs.getBigDecimal("amount"));m.put("reference",rs.getString("reference"));m.put("receivedAt",rs.getDate("received_at").toLocalDate());m.put("reconciled",rs.getBoolean("reconciled"));m.put("reconciliationReference",rs.getString("reconciliation_reference"));m.put("reconciledAt",rs.getTimestamp("reconciled_at")==null?null:rs.getTimestamp("reconciled_at").toInstant());m.put("createdAt",rs.getTimestamp("created_at").toInstant());return m;},id);}

    @PostMapping("/payments/{id}/receipts") @ResponseStatus(HttpStatus.CREATED) @Transactional
    public Map<String,Object> recordReceipt(@PathVariable UUID id,@RequestBody Map<String,Object> body){if(body.keySet().stream().anyMatch(k->!Set.of("amount","reference","receivedAt","version").contains(k)))throw bad("Unsupported receipt field");BigDecimal amount=money(body.get("amount"));String reference=requiredText(body.get("reference"),120);LocalDate received;try{received=LocalDate.parse(requiredText(body.get("receivedAt"),10));if(received.isAfter(LocalDate.now(java.time.Clock.systemUTC())))throw new IllegalArgumentException();}catch(Exception e){throw bad("receivedAt must be a valid date no later than today");}var p=payment(id,true);UUID flat=(UUID)p[0];requirePermission("RENT_MANAGE",flat);long version=((Number)p[3]).longValue();if(integer(body.get("version"),0,Integer.MAX_VALUE)!=version)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Supply the current payment version");Map<?,?> details=readDetails((String)p[2]);BigDecimal due=money(details.get("amount"));BigDecimal paid=db.queryForObject("SELECT COALESCE(SUM(amount),0) FROM rent_payment_receipts WHERE payment_id=?",BigDecimal.class,id);if("PAID".equals(p[1])&&paid.signum()==0)paid=due;if(paid.add(amount).compareTo(due)>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Receipt exceeds the remaining rent balance");UUID receipt=UUID.randomUUID();try{db.update("INSERT INTO rent_payment_receipts(id,payment_id,amount,reference,received_at,created_by) VALUES(?,?,?,?,?,?)",receipt,id,amount,reference,received,access.identity().adminId());}catch(org.springframework.dao.DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Receipt reference is already in use",e);}if(db.update("UPDATE rental_operations SET updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=? AND version=?",id,version)==0)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Payment version is stale");Map<String,Object> result=Map.of("id",receipt,"paymentId",id,"amount",amount,"reference",reference,"receivedAt",received,"reconciled",false);audit.record("RECORD_RENT_RECEIPT","RENT_PAYMENT_RECEIPT",receipt,null,result);return result;}

    @PatchMapping("/payments/{id}/receipts/{receiptId}/reconcile") @Transactional
    public Map<String,Object> reconcile(@PathVariable UUID id,@PathVariable UUID receiptId,@RequestBody Map<String,Object> body){if(body.keySet().stream().anyMatch(k->!Set.of("version","statementReference","statementAmount").contains(k)))throw bad("Unsupported reconciliation field");var p=payment(id,true);UUID flat=(UUID)p[0];requirePermission("RENT_MANAGE",flat);long version=((Number)p[3]).longValue();if(integer(body.get("version"),0,Integer.MAX_VALUE)!=version)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Supply the current payment version");String statement=requiredText(body.get("statementReference"),120);BigDecimal statementAmount=money(body.get("statementAmount"));var receipt=db.query("SELECT amount,reference,reconciled,reconciliation_reference FROM rent_payment_receipts WHERE id=? AND payment_id=?",(rs,n)->new Object[]{rs.getBigDecimal(1),rs.getString(2),rs.getBoolean(3),rs.getString(4)},receiptId,id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(Boolean.TRUE.equals(receipt[2])){if(Objects.equals(statement,receipt[3])&&statementAmount.compareTo((BigDecimal)receipt[0])==0)return Map.of("id",receiptId,"reconciled",true,"reconciliationReference",receipt[3]);throw new ResponseStatusException(HttpStatus.CONFLICT,"Receipt is already reconciled");}if(!Objects.equals(statement,receipt[1])||statementAmount.compareTo((BigDecimal)receipt[0])!=0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Statement reference and amount must exactly match the receipt");try{if(db.update("UPDATE rent_payment_receipts SET reconciled=TRUE,reconciliation_reference=?,reconciled_at=CURRENT_TIMESTAMP WHERE id=? AND NOT reconciled",statement,receiptId)==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Receipt was reconciled concurrently");}catch(org.springframework.dao.DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Statement reference has already been reconciled",e);}if(db.update("UPDATE rental_operations SET updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=? AND version=?",id,version)==0)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Payment version is stale");Map<String,Object> result=Map.of("id",receiptId,"reconciled",true,"reconciliationReference",statement);audit.record("RECONCILE_RENT_RECEIPT","RENT_PAYMENT_RECEIPT",receiptId,Map.of("reconciled",false),result);return result;}

    @PostMapping("/{resource}") @ResponseStatus(HttpStatus.CREATED)
    @Transactional
    public Map<String,Object> create(@PathVariable String resource, @RequestBody Map<String,Object> body) {
        requireResource(resource);
        if("payments".equals(resource))throw new ResponseStatusException(HttpStatus.CONFLICT,"Create a rent schedule and generate its period charge instead");
        UUID flat=uuid(body.get("flatId"));
        validatePayload(resource,body);
        if("maintenance".equals(resource)){body=new LinkedHashMap<>(body);body.put("priority",Objects.toString(body.getOrDefault("priority","NORMAL")).toUpperCase());}
        if("leases".equals(resource)){body=new LinkedHashMap<>(body);body.put("action",body.get("action").toString().toUpperCase());}
        requirePermission(CREATE.get(resource),flat);
        UUID id=UUID.randomUUID(); var actor=access.identity(); UUID member=actor.roles().contains("TENANT")?actor.memberId():null;
        String status=switch(resource){case "payments"->"DUE";case "maintenance"->"OPEN";case "leases"->"DRAFT";default->"AVAILABLE";};
        try { db.update("INSERT INTO rental_operations(id,operation_type,flat_id,member_id,status,details,created_by) VALUES (?,?,?, ?,?,?::jsonb,?)",id,TYPES.get(resource),flat,member,status,json.writeValueAsString(body),actor.adminId()); }
        catch(org.springframework.dao.DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"A matching rent period or viewing slot already exists",e);}
        catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid rental workflow data",e);}
        var result=Map.of("id",id,"flatId",flat,"memberId",member==null?"":member,"status",status,"details",body,"version",0);
        audit.record("CREATE_"+TYPES.get(resource),"RENTAL_OPERATION",id,null,result);
        return result;
    }

    @PatchMapping("/{resource}/{id}")
    @Transactional
    public Map<String,Object> update(@PathVariable String resource,@PathVariable UUID id,@RequestBody Map<String,Object> body){
        requireResource(resource); var current=db.query("SELECT flat_id,member_id,status,details,version FROM rental_operations WHERE id=? AND operation_type=?",(rs,n)->new Object[]{rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getString(3),rs.getString(4),rs.getLong(5)},id,TYPES.get(resource)).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));
        if("payments".equals(resource))throw new ResponseStatusException(HttpStatus.CONFLICT,"Use receipt recording and reconciliation for rent payments");
        UUID flat=(UUID)current[0];
        long version=((Number)current[4]).longValue(); if(!body.containsKey("version")||!(body.get("version") instanceof Number supplied)||supplied.doubleValue()!=supplied.longValue()||supplied.longValue()!=version)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Supply the current record version");
        if("maintenance".equals(resource)&&"CLOSED".equals(current[2])&&body.keySet().stream().anyMatch(k->!"version".equals(k)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Closed maintenance requests cannot be changed");
        Set<String> editable=switch(resource){case "payments"->Set.of("status","version","reference");case "maintenance"->Set.of("status","version","assignedTo","priority","closureDetails");case "leases"->Set.of("status","version","tenantResponseNotes","renewalStartDate","renewalEndDate","rentAmount","securityDeposit","moveOutDate","inspectionDate","depositSettlementAmount","finalizationNotes");default->Set.of("status","version");};
        if(body.keySet().stream().anyMatch(k->!editable.contains(k)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported workflow update field");
        boolean statusChanged=body.containsKey("status")&&!Objects.equals(body.get("status"),current[2]);
        if(!statusChanged&&body.keySet().stream().noneMatch(k->!Set.of("status","version").contains(k)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"No workflow change was supplied");
        String requested=Objects.toString(body.getOrDefault("status",current[2])); String status=requested;
        boolean tenantActor=access.identity().roles().contains("TENANT");
        boolean tenantResponse="leases".equals(resource)&&Set.of("RENEWAL_ACCEPTED","RENEWAL_DECLINED","MOVE_OUT_CONFIRMED").contains(requested);
        if("leases".equals(resource)&&tenantActor&&!tenantResponse)throw new AccessDeniedException("Tenants may only submit renewal or move-out responses");
        if("leases".equals(resource)&&tenantActor&&body.keySet().stream().anyMatch(k->!Set.of("status","version","tenantResponseNotes").contains(k)))throw new AccessDeniedException("Tenant responses cannot change lease terms or finalize the workflow");
        if("leases".equals(resource)&&!tenantActor&&body.containsKey("tenantResponseNotes"))throw new AccessDeniedException("Only the tenant can submit response notes");
        if(tenantResponse){if(!tenantActor)throw new AccessDeniedException("Only the tenant can respond to a lease workflow");requirePermission("LEASE_VIEW",flat);}
        if(access.has(MANAGE.get(resource),"SOCIETY")||access.has(MANAGE.get(resource),"OWN_FLATS")) requirePermission(MANAGE.get(resource),flat);
        else {
            requirePermission("LEASE_VIEW",flat);
            if(!"leases".equals(resource)||!Set.of("RENEWAL_ACCEPTED","RENEWAL_DECLINED","MOVE_OUT_CONFIRMED").contains(requested)||
                    !("RENEWAL_OFFERED".equals(current[2])&&requested.startsWith("RENEWAL_"))&&!("MOVE_OUT_STARTED".equals(current[2])&&"MOVE_OUT_CONFIRMED".equals(requested)))
                throw new AccessDeniedException("Tenants may only respond to their own renewal or move-out workflow");
        }
        if(statusChanged&&!validTransition(resource,current[2].toString(),requested))throw new ResponseStatusException(HttpStatus.CONFLICT,"Invalid workflow status transition");
        if("maintenance".equals(resource)){
            if(body.containsKey("assignedTo")){String assigned=Objects.toString(body.get("assignedTo"),"").trim();if(assigned.length()>120)throw bad("Assignment must be at most 120 characters");if(assigned.isEmpty()&&!"OPEN".equals(current[2]))throw new ResponseStatusException(HttpStatus.CONFLICT,"Active work must remain assigned");body.put("assignedTo",assigned);}
            if(body.containsKey("priority")){String priority=Objects.toString(body.get("priority"),"").toUpperCase();if(!Set.of("LOW","NORMAL","HIGH","URGENT").contains(priority))throw bad("Priority must be LOW, NORMAL, HIGH, or URGENT");body.put("priority",priority);}
            if(statusChanged&&"IN_PROGRESS".equals(requested)){Map<?,?> existing=readDetails((String)current[3]);String assigned=body.containsKey("assignedTo")?Objects.toString(body.get("assignedTo"),""):Objects.toString(existing.get("assignedTo"),"");if(assigned.isBlank())throw new ResponseStatusException(HttpStatus.CONFLICT,"Assign the request before starting work");}
            if(statusChanged&&"RESOLVED".equals(requested)&&Objects.toString(body.get("closureDetails"),"").trim().isBlank())throw bad("Provide closureDetails when resolving the request");
            if(statusChanged&&"CLOSED".equals(requested)){Map<?,?> existing=readDetails((String)current[3]);Object closure=body.getOrDefault("closureDetails",existing.get("closureDetails"));if(Objects.toString(closure,"").trim().isBlank())throw new ResponseStatusException(HttpStatus.CONFLICT,"Resolution details are required before closure");}
            if(body.containsKey("closureDetails")){String closure=Objects.toString(body.get("closureDetails"),"").trim();if(closure.length()>2000)throw bad("closureDetails must be at most 2000 characters");body.put("closureDetails",closure);}
        }
        if(statusChanged&&"leases".equals(resource)&&"DRAFT".equals(current[2])){
            try { Map<?,?> lease=json.readValue((String)current[3],Map.class);String action=Objects.toString(lease.get("action"),"");if(("RENEWAL".equalsIgnoreCase(action)&&!"RENEWAL_OFFERED".equals(requested))||("MOVE_OUT".equalsIgnoreCase(action)&&!"MOVE_OUT_STARTED".equals(requested)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Status must match the selected lease workflow"); }
            catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Stored lease workflow is invalid",e);}
        }
        if("leases".equals(resource))validateLeaseUpdate(current[2].toString(),requested,body,readDetails((String)current[3]),tenantActor);
        Map<String,Object> details=new LinkedHashMap<>(); String encoded;
        try { details.putAll(json.readValue((String)current[3],Map.class));for(String key:editable)if(body.containsKey(key)&&!Set.of("status","version").contains(key))details.put(key,body.get(key));if("leases".equals(resource)&&tenantResponse&&statusChanged){details.put("tenantResponse",status);details.put("tenantRespondedAt",java.time.Instant.now().toString());details.put("tenantRespondedBy",access.identity().memberId());}if("leases".equals(resource)&&"RENEWED".equals(status)&&statusChanged){details.put("previousLeaseEndDate",details.get("leaseEndDate"));details.put("leaseEndDate",details.get("renewalEndDate"));details.put("finalizedAt",java.time.Instant.now().toString());details.put("finalizedBy",access.identity().adminId());}if("leases".equals(resource)&&"COMPLETED".equals(status)&&statusChanged){details.put("finalizedAt",java.time.Instant.now().toString());details.put("finalizedBy",access.identity().adminId());}if("maintenance".equals(resource)&&statusChanged&&"CLOSED".equals(status)){details.put("closedAt",java.time.Instant.now().toString());details.put("closedBy",access.identity().adminId());} encoded=json.writeValueAsString(details); }
        catch(Exception e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Stored workflow data is invalid",e);}
        int changed;
        try { changed=db.update("UPDATE rental_operations SET status=?,details=?::jsonb,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=? AND version=?",status,encoded,id,version); }
        catch(org.springframework.dao.DataIntegrityViolationException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"A matching rent period or viewing slot already exists",e);}
        if(changed==0)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Record version is stale");
        if("maintenance".equals(resource)&&(statusChanged||body.containsKey("assignedTo")||body.containsKey("priority")||body.containsKey("closureDetails"))){String note=statusChanged&&"RESOLVED".equals(status)?"Request resolved: "+details.get("closureDetails"):statusChanged?"Status changed from "+current[2]+" to "+status:body.containsKey("assignedTo")?"Assignment updated":body.containsKey("priority")?"Priority updated":"Resolution details updated";addMaintenanceProgress(id,note,status,Objects.toString(details.get("assignedTo"),null),access.identity().adminId());}
        audit.record("UPDATE_"+TYPES.get(resource),"RENTAL_OPERATION",id,Map.of("status",current[2],"details",current[3]),Map.of("status",status,"details",details));
        return Map.of("id",id,"flatId",flat,"memberId",current[1]==null?"":current[1],"status",status,"details",details,"version",version+1);
    }

    @GetMapping("/maintenance/{id}/progress")
    public List<Map<String,Object>> maintenanceProgress(@PathVariable UUID id){var current=maintenance(id,false);requirePermission("MAINTENANCE_VIEW",(UUID)current[0]);return db.query("SELECT id,note,status,assigned_to,created_by,created_at FROM maintenance_progress_updates WHERE maintenance_id=? ORDER BY created_at,id",(rs,n)->Map.of("id",rs.getObject("id",UUID.class),"note",rs.getString("note"),"status",rs.getString("status"),"assignedTo",Objects.toString(rs.getString("assigned_to"),""),"createdBy",rs.getObject("created_by",UUID.class),"createdAt",rs.getTimestamp("created_at").toInstant()),id);}

    @PostMapping("/maintenance/{id}/progress") @ResponseStatus(HttpStatus.CREATED) @Transactional
    public Map<String,Object> addMaintenanceProgress(@PathVariable UUID id,@RequestBody Map<String,Object> body){if(body.keySet().stream().anyMatch(k->!Set.of("note","version").contains(k)))throw bad("Only note and version are accepted");String note=requiredText(body.get("note"),2000);var current=maintenance(id,true);UUID flat=(UUID)current[0];requirePermission("MAINTENANCE_MANAGE",flat);if(Set.of("RESOLVED","CLOSED").contains(current[1]))throw new ResponseStatusException(HttpStatus.CONFLICT,"Progress cannot be added after resolution");long version=((Number)current[3]).longValue();if(integer(body.get("version"),0,Integer.MAX_VALUE)!=version)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Supply the current request version");if(db.update("UPDATE rental_operations SET updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=? AND version=?",id,version)==0)throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Request version is stale");Map<?,?> details=readDetails((String)current[2]);UUID updateId=UUID.randomUUID();addMaintenanceProgress(updateId,id,note,(String)current[1],Objects.toString(details.get("assignedTo"),null),access.identity().adminId());Map<String,Object> result=Map.of("id",updateId,"maintenanceId",id,"note",note,"status",current[1],"version",version+1);audit.record("ADD_MAINTENANCE_PROGRESS","MAINTENANCE_PROGRESS",updateId,null,result);return result;}

    private Object[] maintenance(UUID id,boolean lock){String sql="SELECT flat_id,status,details,version FROM rental_operations WHERE id=? AND operation_type='MAINTENANCE'"+(lock?" FOR UPDATE":"");return db.query(sql,(rs,n)->new Object[]{rs.getObject(1,UUID.class),rs.getString(2),rs.getString(3),rs.getLong(4)},id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
    private void addMaintenanceProgress(UUID id,String note,String status,String assignedTo,UUID actor){addMaintenanceProgress(UUID.randomUUID(),id,note,status,assignedTo,actor);}
    private void addMaintenanceProgress(UUID progressId,UUID id,String note,String status,String assignedTo,UUID actor){db.update("INSERT INTO maintenance_progress_updates(id,maintenance_id,note,status,assigned_to,created_by) VALUES(?,?,?,?,?,?)",progressId,id,note,status,assignedTo,actor);}
    @PostMapping("/viewings/{id}/book")
    @Transactional
    public Map<String,Object> bookViewing(@PathVariable UUID id){
        var record=db.query("SELECT flat_id,status,version FROM rental_operations WHERE id=? AND operation_type='VIEWING'",(rs,n)->new Object[]{rs.getObject(1,UUID.class),rs.getString(2),rs.getLong(3)},id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));
        UUID flat=(UUID)record[0];requirePermission("VIEWING_BOOK",flat);if(!"AVAILABLE".equals(record[1]))throw new ResponseStatusException(HttpStatus.CONFLICT,"Viewing slot is no longer available");
        var actor=access.identity();int changed=db.update("UPDATE rental_operations SET status='BOOKED',member_id=?,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=? AND status='AVAILABLE' AND version=?",actor.memberId(),id,record[2]);if(changed==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Viewing slot is no longer available");
        Map<String,Object> result=Map.of("id",id,"flatId",flat,"status","BOOKED","memberId",actor.memberId()==null?"":actor.memberId());
        audit.record("BOOK_VIEWING","RENTAL_OPERATION",id,Map.of("status","AVAILABLE"),result);
        return result;
    }
    private void requirePermission(String permission,UUID flat){var actor=access.identity(); if(actor==null)throw new AccessDeniedException("Authentication required");
        if(access.has(permission,"SOCIETY"))return;
        if(flat==null||!access.has(permission,"OWN_FLATS")||!actor.flatIds().contains(flat))throw new AccessDeniedException("Permission denied for this flat");
    }
    private void requireResource(String resource){if(!TYPES.containsKey(resource))throw new ResponseStatusException(HttpStatus.NOT_FOUND);}
    private void validatePayload(String resource,Map<String,Object> body){
        Set<String> allowed=switch(resource){case "payments"->Set.of("flatId","period","amount","dueDate","reference");case "maintenance"->Set.of("flatId","summary","description","priority");case "leases"->Set.of("flatId","leaseEndDate","action","rentAmount","securityDeposit","renewalStartDate","renewalEndDate","moveOutDate","notes");default->Set.of("flatId","slot","notes");};
        if(body.keySet().stream().anyMatch(k->!allowed.contains(k)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported rental workflow field");
        List<String> required=switch(resource){case "payments"->List.of("period","amount","dueDate");case "maintenance"->List.of("summary","description");case "leases"->List.of("leaseEndDate","action");default->List.of("slot");};
        if(required.stream().anyMatch(k->body.get(k)==null||body.get(k).toString().isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Missing required fields: "+String.join(", ",required));
        try {
            if("payments".equals(resource)){if(new java.math.BigDecimal(body.get("amount").toString()).signum()<=0)throw new IllegalArgumentException();java.time.LocalDate.parse(body.get("dueDate").toString());if(!body.get("period").toString().matches("\\d{4}-(0[1-9]|1[0-2])"))throw new IllegalArgumentException();}
            if("leases".equals(resource)){dateValue(body.get("leaseEndDate"),"leaseEndDate");String action=body.get("action").toString().toUpperCase();if(!Set.of("RENEWAL","MOVE_OUT").contains(action))throw new IllegalArgumentException();if("RENEWAL".equals(action)){if(body.get("rentAmount")==null||body.get("securityDeposit")==null)throw new IllegalArgumentException();Map<String,Object> values=new HashMap<>(body);validateRenewalTerms(values);}else dateValue(body.get("moveOutDate"),"moveOutDate");if(body.get("rentAmount")!=null&&!body.get("rentAmount").toString().isBlank())money(body.get("rentAmount"));if(body.get("securityDeposit")!=null&&!body.get("securityDeposit").toString().isBlank())nonNegativeMoney(body.get("securityDeposit"));}
            if("viewings".equals(resource))java.time.OffsetDateTime.parse(body.get("slot").toString());
            if("maintenance".equals(resource)&&body.containsKey("priority")&&!Set.of("LOW","NORMAL","HIGH","URGENT").contains(body.get("priority").toString().toUpperCase()))throw new IllegalArgumentException();
            if("maintenance".equals(resource)&&(body.get("summary").toString().trim().length()>160||body.get("description").toString().trim().length()>2000))throw new IllegalArgumentException();
        }catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid date, amount, or workflow action");}
    }
    private boolean validTransition(String resource,String from,String to){return switch(resource){
        case "payments" -> Set.of("DUE>PAID","OVERDUE>PAID").contains(from+">"+to);
        case "maintenance" -> Set.of("OPEN>IN_PROGRESS","OPEN>RESOLVED","IN_PROGRESS>RESOLVED","RESOLVED>CLOSED").contains(from+">"+to);
        case "leases" -> Set.of("DRAFT>RENEWAL_OFFERED","DRAFT>MOVE_OUT_STARTED","RENEWAL_OFFERED>RENEWAL_ACCEPTED","RENEWAL_OFFERED>RENEWAL_DECLINED","MOVE_OUT_STARTED>MOVE_OUT_CONFIRMED","MOVE_OUT_CONFIRMED>COMPLETED","RENEWAL_ACCEPTED>RENEWED","RENEWAL_DECLINED>MOVE_OUT_STARTED").contains(from+">"+to);
        case "viewings" -> Set.of("AVAILABLE>CANCELLED","BOOKED>CANCELLED").contains(from+">"+to);
        default -> false;
    };}
    private UUID uuid(Object v){try{return UUID.fromString(Objects.toString(v));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"flatId must be a UUID");}}
    private void requireRentView(UUID flat){var a=access.identity();if(a==null||(!access.has("RENT_VIEW","SOCIETY")&&(!access.has("RENT_VIEW","OWN_FLATS")||a.flatIds().isEmpty()||(flat!=null&&!a.flatIds().contains(flat)))))throw new AccessDeniedException("Permission denied for rent schedules");}
    private Object[] payment(UUID id,boolean lock){String sql="SELECT flat_id,status,details,version FROM rental_operations WHERE id=? AND operation_type='PAYMENT'"+(lock?" FOR UPDATE":"");return db.query(sql,(rs,n)->new Object[]{rs.getObject(1,UUID.class),rs.getString(2),rs.getString(3),rs.getLong(4)},id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
    private BigDecimal money(Object v){try{BigDecimal n=new BigDecimal(Objects.toString(v)).setScale(2,RoundingMode.UNNECESSARY);if(n.signum()<=0||n.precision()>12)throw new IllegalArgumentException();return n;}catch(Exception e){throw bad("Amount must be a positive value with at most two decimals");}}
    private int integer(Object v,int min,int max){try{if(!(v instanceof Number n)||n.doubleValue()!=n.intValue()||n.intValue()<min||n.intValue()>max)throw new IllegalArgumentException();return n.intValue();}catch(Exception e){throw bad("Integer value is outside the allowed range");}}
    private String period(Object v){String p=requiredText(v,7);try{if(!p.matches("\\d{4}-(0[1-9]|1[0-2])"))throw new IllegalArgumentException();YearMonth.parse(p);return p;}catch(Exception e){throw bad("Period must use YYYY-MM format");}}
    private String requiredText(Object v,int max){String s=Objects.toString(v,"").trim();if(s.isEmpty()||s.length()>max)throw bad("Required text is empty or too long");return s;}
    @SuppressWarnings("unchecked") private Map<?,?> readDetails(String s){try{return json.readValue(s,Map.class);}catch(Exception e){throw new IllegalStateException(e);}}
    private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
    private Map<String,Object> schedule(UUID id,UUID flat,BigDecimal amount,int day,String start,String end,boolean active,long version){Map<String,Object> m=new LinkedHashMap<>();m.put("id",id);m.put("flatId",flat);m.put("amount",amount);m.put("dueDay",day);m.put("startPeriod",start);m.put("endPeriod",end);m.put("active",active);m.put("version",version);return m;}
    @SuppressWarnings("unchecked")
    private Map<String,Object> row(UUID id,UUID flat,UUID member,String status,String details,UUID actor,Object created,Object updated,long version){try{return Map.of("id",id,"flatId",flat,"memberId",member==null?"":member,"status",status,"details",(Map<String,Object>)json.readValue(details,Map.class),"createdBy",actor,"createdAt",created,"updatedAt",updated,"version",version);}catch(Exception e){throw new IllegalStateException(e);}}
}
